mapper.select:
WITH candidate AS (
  SELECT id FROM job_run
   WHERE status='PENDING' AND batch_key IS NOT NULL AND available_at<=#{p.now}
     AND attempt_count < max_attempts AND job_type IN
     #{type}
   ORDER BY available_at,created_at,id FOR UPDATE SKIP LOCKED LIMIT 1
)
UPDATE job_run j SET status='RUNNING',started_at=COALESCE(started_at,#{p.now}),
  attempt_count=attempt_count+1,lease_owner=#{p.owner},lease_expires_at=#{p.leaseUntil},
  cancel_requested=false,updated_at=#{p.now}
FROM candidate WHERE j.id=candidate.id RETURNING j.*

mapper.update:

UPDATE job_run SET status='PENDING', processed_count=processed_count+#{p.count}, attempt_count=0,
    lease_owner=NULL, lease_expires_at=NULL, cancel_requested=false, error_summary=NULL, updated_at=#{p.now}
WHERE id=#{p.id} AND status='RUNNING' AND lease_owner=#{p.owner}


UPDATE job_run SET status=#{p.status}, finished_at=CASE WHEN #{p.retry} THEN NULL::timestamptz ELSE #{p.now} END,
    error_summary=#{p.error}, lease_owner=NULL, lease_expires_at=NULL, cancel_requested=false, updated_at=#{p.now}
WHERE id=#{p.id} AND status='RUNNING' AND lease_owner=#{p.owner}


UPDATE job_run SET status=CASE WHEN #{p.retry} THEN 'PENDING' ELSE 'FAILED' END,
    finished_at=CASE WHEN #{p.retry} THEN NULL::timestamptz ELSE #{p.now} END, error_summary=#{p.error},
    lease_owner=NULL, lease_expires_at=NULL, cancel_requested=false, updated_at=#{p.now}
WHERE id=#{p.id} AND status='RUNNING' AND lease_expires_at <= #{p.now}


UPDATE job_run SET status=#{p.status}, processed_count=processed_count+#{p.count}, finished_at=#{p.now},
    error_summary=#{p.error}, lease_owner=NULL, lease_expires_at=NULL, cancel_requested=false, updated_at=#{p.now}
WHERE id=#{p.id} AND status='RUNNING' AND lease_owner=#{p.owner}
